if ! command -v psql &> /dev/null; then
    echo "ERROR: psql command not found. Please install PostgreSQL client."
    exit 1
fi

# Check if SQL directory exists
if [ ! -d "${SQL_DIR}" ]; then
    echo "ERROR: SQL directory not found: ${SQL_DIR}"
    exit 1
fi

