echo
if [[ ! $REPLY =~ ^[Yy]$ ]]; then
    echo "Aborted."
    exit 0
fi

# Run each downgrade
for file in ${DOWN_FILES}; do
    filename=$(basename "${file}")
    echo "Applying: ${filename}..."

    if psql "${DATABASE_URL}" -f "${file}" -v ON_ERROR_STOP=1; then
